// Export-parity guard for napi's generated ESM entry and local build
// artifacts.
//
// `index.js` and `index.d.ts` are generated by `napi build --esm`; the .d.ts
// is the source of truth for the native API. Platform binaries are not in the
// root tarball: `napi prepublish` copies them into per-triple optional
// dependency packages, so this guard checks whichever local `.node` artifacts
// a build left in this directory (skipping artifacts for other platforms).
// This check fails if the ESM entry, its declarations, and a local binary
// disagree, or if the entry falls back to CommonJS.
//
// Run: `node check-exports.js` (from `src/node/`). Exit non-zero lists the
// missing names per file or binary.
import { existsSync, readdirSync, readFileSync } from 'node:fs'
import { createRequire } from 'node:module'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const require = createRequire(import.meta.url)
const dir = dirname(fileURLToPath(import.meta.url))

const bindingTargetExport = '__napiBindingTarget'
const isApiName = (name) => name !== bindingTargetExport && !name.startsWith('__napi')

const entrySource = readFileSync(join(dir, 'index.js'), 'utf8')
if (!/^import\s/m.test(entrySource) || /^\s*module\.exports\s*[.=]/m.test(entrySource)) {
  console.error('check-exports: index.js is not an ESM binding; build with `napi build --esm`')
  process.exit(1)
}

const destructuredNames = (source) => {
  const match = source.match(/const\s*\{([^}]+)\}\s*=\s*nativeBinding/)
  if (!match) {
    console.error('check-exports: no `const { ... } = nativeBinding` found in index.js')
    return null
  }
  return match[1].split(',').map((s) => s.trim()).filter(Boolean)
}

const declaredNames = (source) => {
  const names = new Set()
  const declaration = /\bexport\s+(?:declare\s+)?(?:function|class|const|let|var)\s+([A-Za-z_$][\w$]*)/g
  for (const match of source.matchAll(declaration)) names.add(match[1])
  return [...names].filter(isApiName)
}

const exported = destructuredNames(entrySource)
if (exported === null || exported.length === 0) {
  console.error('check-exports: empty export list in index.js')
  process.exit(2)
}

if (!existsSync(join(dir, 'index.d.ts'))) {
  console.error('check-exports: index.d.ts is missing; run `npm run build`')
  process.exit(2)
}

const declared = declaredNames(readFileSync(join(dir, 'index.d.ts'), 'utf8'))
const missingFromEntry = declared.filter((name) => !exported.includes(name))
const missingFromTypes = exported.filter((name) => !declared.includes(name))
if (missingFromEntry.length > 0 || missingFromTypes.length > 0) {
  if (missingFromEntry.length > 0) {
    console.error(`check-exports: index.js is missing declared exports: ${missingFromEntry.join(', ')}`)
  }
  if (missingFromTypes.length > 0) {
    console.error(`check-exports: index.d.ts is missing entry exports: ${missingFromTypes.join(', ')}`)
  }
  process.exit(1)
}

const binaries = readdirSync(dir).filter((f) => f.endsWith('.node'))
if (binaries.length === 0) {
  console.error('check-exports: no local `.node` artifacts found; run `npm run build`')
  process.exit(2)
}

let failed = false
for (const file of binaries) {
  let binding
  try {
    binding = require(join(dir, file))
  } catch (e) {
    // A binary for another platform/arch cannot load here; skip it rather
    // than fail — CI/dev machines only ever load their own triple.
    console.log(`check-exports: skipping unloadable ${file} (${e.code || e.message})`)
    continue
  }
  const missing = exported.filter((name) => typeof binding[name] === 'undefined')
  if (missing.length > 0) {
    console.error(`check-exports: ${file} is missing exports: ${missing.join(', ')}`)
    failed = true
  } else {
    console.log(`check-exports: ${file} OK (${exported.length} exports)`)
  }
}
process.exit(failed ? 1 : 0)
